public async ValueTask<bool> AuthorizeAsync(
    McpRequestContext context,
    CancellationToken ct = default)
{
    var clientId = context.Authentication?.ClientId;
    var requiredRole = _tool.RequiredRole;

    if (string.IsNullOrEmpty(clientId))
    {
        _logger.LogWarning("Unauthenticated tool access attempted for {Tool}.", _tool.Name);
        return false;
    }

    var hasRole = await _authorization.HasRoleAsync(clientId, requiredRole, ct);
    if (!hasRole)
        _logger.LogWarning("Forbidden tool access: {Tool} for {ClientId}.", _tool.Name, clientId);

    return hasRole;
}
